import React, { useEffect, useState, useRef } from "react";
import { Link, useNavigate } from "react-router-dom";
import Logo from "../assets/Logo.png";

export const Navigation = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [dropdownVisible, setDropdownVisible] = useState(false);
  const dropdownRef = useRef(null);
  const navigate = useNavigate();
  const [avatar, setAvatar] = useState("/assets/default-avatar.png");

  useEffect(() => {
    const token = localStorage.getItem("token");
    setIsLoggedIn(!!token);

    const ownerData = localStorage.getItem("owner");
    if (ownerData) {
      try {
        const owner = JSON.parse(ownerData);
        setAvatar(owner.avatar || "/assets/default-avatar.png");
      } catch (error) {
        console.error("Error parsing owner data:", error);
      }
    }
  }, []);

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
        setDropdownVisible(false);
      }
    };
    document.addEventListener("click", handleClickOutside);
    return () => {
      document.removeEventListener("click", handleClickOutside);
    };
  }, []);

  const handleLogout = () => {
    localStorage.removeItem("token");
    localStorage.removeItem("ownerId");
    setIsLoggedIn(false);
    setAvatar("/assets/default-avatar.png");
    navigate("/login");
  };

  const toggleDropdown = (event) => {
    event.stopPropagation();
    setDropdownVisible((prev) => !prev);
  };

  const handleProfileClick = () => {
    const ownerId = localStorage.getItem("ownerId");
    if (ownerId) {
      navigate(`/profile/${ownerId}`);
    }
  };

  return (
    <nav className="navbar">
      <div className="container">
        <Link to="/" className="navbar-brand">
          <img src={Logo} alt="Petopia Logo" className="logo" />
        </Link>
        <ul className="nav-links">
          {!isLoggedIn ? (
            <>
              <li><Link to="/" className="nav-link">Home</Link></li>
              <li><Link to="/login" className="nav-link">Log In</Link></li>
            </>
          ) : (
            <li className="dropdown" ref={dropdownRef}>
              <img
                src={avatar}
                alt="Profile"
                className="avatar"
                onClick={toggleDropdown}
              />
              {dropdownVisible && (
                <div className="dropdown-menu">
                  <div className="dropdown-item" onClick={handleProfileClick}>Profile</div>
                  <div className="dropdown-item" onClick={handleLogout}>Logout</div>
                </div>
              )}
            </li>
          )}
        </ul>
      </div>
    </nav>
  );
};
